mapper.select:
SELECT 
  FROM dcr21_relate_icr a
       INNER JOIN icr01_class_tree b ON a.dcr21_icr_class_tree_id = b.icr01_class_tree_id
 WHERE a.dcr21_company_id = #{companyId}
   AND a.dcr21_relate_icr_id IN
#{id}

mapper.delete:
DELETE FROM dcr21_relate_icr
 WHERE dcr21_dcr_class_tree_id = #{dcrClassTreeId}
   AND dcr21_icr_class_tree_id = #{icrClassTreeId}
   AND dcr21_company_id        = #{companyId}

DELETE FROM dcr21_relate_icr
 WHERE dcr21_company_id = #{companyId}
   AND dcr21_relate_icr_id IN
#{id}
